46	// 一次性提交全部字节。
47	std::string hash_whole(const std::vector<unsigned char>& data) {
48	    branchaudit::Sha256 sha;
49	    sha.update(data.data(), data.size());
50	    return hex_of(sha.final());
51	}
52	
53	// 按给定偏移分段提交（偏移为相对起点的累计切分点，0 与 data.size() 可省略）。
54	std::string hash_parts(const std::vector<unsigned char>& data,
55	                       const std::vector<std::size_t>& cuts) {
56	    branchaudit::Sha256 sha;
57	    std::size_t prev = 0;
58	    for (std::size_t cut : cuts) {
59	        sha.update(data.data() + prev, cut - prev);
60	        prev = cut;
61	    }
62	    sha.update(data.data() + prev, data.size() - prev);
63	    return hex_of(sha.final());
64	}
65	
66	std::vector<unsigned char> fill_a(std::size_t n) {
67	    return std::vector<unsigned char>(n, static_cast<unsigned char>('a'));
68	}
69	
70	// 确定性字节序列，覆盖 0x00 与 0xff。
71	std::vector<unsigned char> pattern(std::size_t n) {
72	    std::vector<unsigned char> v(n);
73	    for (std::size_t i = 0; i < n; ++i) {
74	        v[i] = static_cast<unsigned char>((i * 31 + 7) % 256);
75	    }
76	    return v;
77	}
78	
79	void expect_digest(std::string_view label, const std::vector<unsigned char>& data,
80	                   std::string_view expected) {
81	    check(hash_whole(data) == expected, label);
82	}
