171	// ---- 增量接口：一次提交与任意分段必须一致 ---------------------------------
172	
173	void test_incremental_splits() {
174	    const std::size_t sizes[] = {0, 1, 2, 3, 55, 56, 63, 64, 65, 66,
175	                                 127, 128, 129, 200, 255, 256, 257};
176	    for (std::size_t n : sizes) {
177	        const std::vector<unsigned char> data = pattern(n);
178	        const std::string whole = hash_whole(data);
179	        // 每个切分点都试：含空段、恰好在 64 字节边界上、把边界两侧拆开。
180	        for (std::size_t cut = 0; cut <= n; ++cut) {
181	            check(hash_parts(data, {cut}) == whole,
182	                  "2-way split n=" + std::to_string(n) + " cut=" + std::to_string(cut));
183	        }
184	    }
185	
186	    // 较大输入上围绕分组边界的三分段组合。
187	    {
188	        const std::size_t n = 200;
189	        const std::vector<unsigned char> data = pattern(n);
190	        const std::string whole = hash_whole(data);
191	        const std::size_t points[] = {0, 1, 7, 55, 56, 63, 64, 65,
192	                                      127, 128, 129, 135, 199, 200};
193	        for (std::size_t c1 : points) {
194	            for (std::size_t c2 : points) {
195	                if (c1 > c2) continue;
196	                check(hash_parts(data, {c1, c2}) == whole,
197	                      "3-way split 200 @ " + std::to_string(c1) + "," +
198	                      std::to_string(c2));
199	            }
200	        }
201	    }
202	
203	    // 手工构造的对抗性分段：边界两侧逐字节拆开，缓冲区跨多次 update 填满。
204	    {
205	        const std::vector<unsigned char> data = pattern(300);
206	        const std::string whole = hash_whole(data);
207	        const std::size_t plans[][5] = {
208	            {63, 64, 64, 65, 44},   // 300 = 63+64+64+65+44
209	            {1, 64, 64, 64, 107},   // 300 = 1+64*3+107
210	            {56, 8, 56, 8, 172},
211	            {55, 1, 55, 1, 188},
212	        };
213	        for (const auto& plan : plans) {
214	            branchaudit::Sha256 sha;
215	            std::size_t off = 0;
216	            for (std::size_t len : plan) {
217	                sha.update(data.data() + off, len);
218	                off += len;
219	            }
220	            check(off == 300 && hex_of(sha.final()) == whole,
221	                  "adversarial segmented update");
222	        }
223	    }
224	}
