251	// 调用库接口期间截获标准输出/错误：库只返回结果，不自行打印。
252	std::pair<std::string, std::string> silent_file_hash(const fs::path& p,
253	                                                     branchaudit::FileHashResult* out) {
254	    std::stringstream cap_out, cap_err;
255	    auto* old_out = std::cout.rdbuf(cap_out.rdbuf());
256	    auto* old_err = std::cerr.rdbuf(cap_err.rdbuf());
257	    *out = branchaudit::sha256_file(p);
258	    std::cout.rdbuf(old_out);
259	    std::cerr.rdbuf(old_err);
260	    return {cap_out.str(), cap_err.str()};
261	}
