417	// ---- 文件失败行为：存在却打不开 / 部分读取后继续读出错 --------------------
418	//
419	// 这两类错误无法用“缺失路径/目录”夹具制造：文件真实存在、打开成功，
420	// 错误分别发生在 open 与后续 read 上。通过随测试预载的故障注入库在
421	// libc 文件访问接口处确定性触发（见 tests/fault_inject.c），因此被测
422	// 代码走的是与生产完全相同的“定位 -> 打开 -> 流式读取 -> 错误传播”
423	// 路径，而不是构造一个带错误文字的返回值。
424	
425	void test_file_io_failures() {
426	    TempArea tmp("iofail");
427	
428	    // 打开失败与读取失败共用的夹具：文件确定存在、内容确定。
429	    const fs::path existing = tmp.root / "present 存在.bin";
430	    constexpr long kPartial = 40;
431	    const std::vector<unsigned char> bytes = pattern(200);
432	    write_file(existing, bytes);
433	
434	    // 同一文件不注入时必须成功，证明失败确由文件访问错误引起，而不是
435	    // 针对该路径写死的错误结果。
436	    {
437	        branchaudit::FileHashResult r;
438	        auto captured = silent_file_hash(existing, &r);
439	        check(r.ok() && hex_of(r.digest) == hash_whole(bytes),
440	              "iofail fixture: succeeds without injected fault");
441	        check(captured.first.empty() && captured.second.empty(),
442	              "iofail fixture: library stays silent on success");
443	    }
444	
445	    // ---- 文件确实存在却不能打开 ----------------------------------------
446	    {
447	        fault_test::FaultTrigger trigger(
448	            "BRANCHAUDIT_TEST_OPEN_FAIL", existing.string());
449	        branchaudit::FileHashResult r;
450	        auto captured = silent_file_hash(existing, &r);
451	        check(!r.ok(), "existing-but-unopenable: failure result");
452	        check(r.error.find(existing.string()) != std::string::npos,
453	              "open failure: error names the failed path");
454	        check(r.error.find("ermission") != std::string::npos ||
455	                  r.error.find("denied") != std::string::npos ||
456	                  r.error.find("cces") != std::string::npos,
457	              "open failure: error states an open/permission reason");
458	        check(r.error.size() > existing.string().size() + 2,
459	              "open failure: error gives reason beyond the path");
460	        check(captured.first.empty() && captured.second.empty(),
461	              "open failure: library only returns result, prints nothing");
462	    }
463	    // 触发变量离开作用域后，同一文件恢复成功。
464	    {
465	        branchaudit::FileHashResult r;
466	        silent_file_hash(existing, &r);
467	        check(r.ok(), "open trigger scoped: later access succeeds again");
468	    }
469	
470	    // ---- 文件已打开、取得部分内容后继续读取时出错 ----------------------
471	    {
472	        fault_test::FaultTrigger trigger(
473	            "BRANCHAUDIT_TEST_READ_FAIL",
474	            existing.string() + ":" + std::to_string(kPartial));
475	        branchaudit::FileHashResult r;
476	        auto captured = silent_file_hash(existing, &r);
477	        check(!r.ok(), "read error after partial content: failure result");
478	        check(r.error.find(existing.string()) != std::string::npos,
479	              "read failure: error names the failed path");
480	        check(r.error.find("read") != std::string::npos,
481	              "read failure: error states it is a read failure (not EOF)");
482	        check(r.error.size() > existing.string().size() + 2,
483	              "read failure: error gives reason beyond the path");
484	        check(captured.first.empty() && captured.second.empty(),
485	              "read failure: library only returns result, prints nothing");
486	
487	        // 已读到的部分内容绝不能成为成功摘要：既不是完整文件摘要，也不
488	        // 是前 kPartial 字节的摘要。
489	        const std::string got = hex_of(r.digest);
490	        check(got != hash_whole(bytes),
491	              "read failure: digest is not the whole-file summary");
492	        check(got != hash_whole(std::vector<unsigned char>(
493	                      bytes.begin(), bytes.begin() + kPartial)),
494	              "read failure: already-read partial content is not a success digest");
495	    }
496	
497	    // ---- 空文件正常读完仍然成功：没有读到内容不等于读错误 --------------
498	    const fs::path empty = tmp.root / "empty 空.bin";
499	    write_file(empty, {});
500	    {
501	        fault_test::FaultTrigger trigger(
502	            "BRANCHAUDIT_TEST_READ_FAIL",
503	            empty.string() + ":" + std::to_string(kPartial));
504	        branchaudit::FileHashResult r;
505	        auto captured = silent_file_hash(empty, &r);
506	        check(r.ok(), "empty file read to completion: still success under read-fault arm");
507	        check(hex_of(r.digest) ==
508	                  "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
509	              "empty file still yields SHA-256 of empty sequence");
510	        check(captured.first.empty() && captured.second.empty(),
511	              "empty file: library stays silent");
512	    }
513	
514	    // ---- 触发只作用于指定路径：其他文件不受影响 ------------------------
515	    const fs::path other = tmp.root / "other.bin";
516	    write_file(other, bytes);
517	    {
518	        fault_test::FaultTrigger trigger(
519	            "BRANCHAUDIT_TEST_READ_FAIL",
520	            existing.string() + ":" + std::to_string(kPartial));
521	        branchaudit::FileHashResult r;
522	        silent_file_hash(other, &r);
523	        check(r.ok() && hex_of(r.digest) == hash_whole(bytes),
524	              "fault is path-scoped: unrelated file still hashes correctly");
525	    }
526	}
527	
528	// ---- to_hex 格式 ----------------------------------------------------------
529	
530	void test_hex_format() {
531	    branchaudit::Sha256 sha;
532	    const auto digest = sha.final();  // 空输入摘要
533	    const std::string hex = branchaudit::to_hex(digest);
534	    check(hex.size() == 64, "to_hex returns 64 characters");
535	    bool lowercase = true;
536	    for (char ch : hex) {
537	        const bool ok_digit = (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f');
538	        if (!ok_digit) lowercase = false;
539	    }
540	    check(lowercase, "to_hex is lowercase hexadecimal");
541	    check(hex == "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
542	          "to_hex of empty digest matches standard");
543	}
544	
545	}  // namespace
546	
547	int main(int argc, char** argv) {
548	    fault_test::ensure_fault_preloaded(argc, argv);
549	
550	    test_standard_vectors();
551	    test_byte_semantics();
552	    test_boundary_lengths();
553	    test_incremental_splits();
554	    test_file_hashing();
555	    test_file_failures();
556	    if (fault_test::kFaultInjectionAvailable) {
557	        test_file_io_failures();
558	    } else {
559	        // 平台无 LD_PRELOAD//proc 故障注入支持（如 macOS）：明确报告
560	        // 跳过，不计入已通过检查。
561	        ++g_skipped;
562	        std::cout << "SKIP: existing-but-unopenable and mid-read-error "
563	                     "checks (fault injection not supported on this platform)\n";
564	    }
565	    test_hex_format();
566	
567	    if (g_failures == 0) {
568	        std::cout << "all " << g_checks << " sha256 regression checks passed";
569	        if (g_skipped > 0) {
570	            std::cout << " (" << g_skipped << " platform-specific check group"
571	                         " skipped, not verified)";
572	        }
573	        std::cout << '\n';
